							[96785] = "Ain't No Telling",
						},
						qlvl = 36,
						quest = 96786,
						t = "accept",
						title = "The Syndicate Sting",
						x = 26.8,
						y = 64.4,
					},
				},
				note = "She will not talk without something to bargain with. Her stash is upstairs in a house close to the keep: take the {item:275709}. If it is already open, wait for it to come back.",
				title = "{quest:96785}",
			},
			{
				goals = {
					{
						level = 35,
						t = "level",
					},
					{
						count = 1,
						f = "e",
						item = 275882,
						itemName = "Intercepted Shipment",
						map = 1417,
						oi = 1,
						quest = 96786,
						t = "collect",
						title = "The Syndicate Sting",
						x = 15.5,
						y = 43,
					},
				},
				note = "Falconcrest's men make the handoff at the southern end of {area:1057}, the old wall between Arathi and {area:287}. Kill the two guarding the box and take the {item:275882}. Keep the {item:275706}: {npc:13085} wants it back with the shipment.",
				title = "{quest:96786}",
			},
			{
				goals = {
					{
						map = 1416,
						note = "{npc:13085}: 70 silver, 300 {npc:13936} reputation",
						npc = 13085,
						npcName = "Myrokos Silentform",
						quest = 96786,
						t = "turnin",
						title = "The Syndicate Sting",
						x = 84.88,
						y = 80.46,
						z = 195.1,
					},
				},
				title = "Back to {npc:13085}",
			},
		},
		title = "{npc:13936}",
		version = 1,
		why = "Opens {area:3486}, the hidden rogue house in the Alterac hills, and {npc:13085}'s jobs against the Syndicate.",
		written = {
			["Back to {npc:13085}"] = "Back to Myrokos",
			["Back to {npc:13085}; the report sends you after the Perenolde heirlooms. Two towers stand among the {area:281}, in the middle of the {zone:1416}, held by ogres: the shield lies in the northern tower, the sword in the southern one, which elite ogres ring and watch from far off. Stay stealthed; nothing guards the heirlooms inside."] = "Back to Myrokos; the report sends you after the Perenolde heirlooms. Two towers stand among the Ruins of Alterac, in the middle of the Alterac Mountains, held by ogres: the shield lies in the northern tower, the sword in the southern one, which elite ogres ring and watch from far off. Stay stealthed; nothing guards the heirlooms inside.",
			["Falconcrest's men make the handoff at the southern end of {area:1057}, the old wall between Arathi and {area:287}. Kill the two guarding the box and take the {item:275882}. Keep the {item:275706}: {npc:13085} wants it back with the shipment."] = "Falconcrest's men make the handoff at the southern end of Thoradin's Wall, the old wall between Arathi and Hillsbrad. Kill the two guarding the box and take the Intercepted Shipment. Keep the Syndicate Uniform: Myrokos wants it back with the shipment.",
			["In your mid 30s {npc:13085} has two more jobs; take both. {npc:266357} leads a Syndicate scouting party at {area:280}, in the east of the {zone:1416}, inside one of the houses with stealthed Syndicate around him. Pick his pocket for the report and do not kill him: he does not drop it. If you are lower than him he sees through stealth; Master of Deception helps, or Distract him, Vanish and come in from behind. {spell:921} can miss several times in a row."] = "In your mid 30s Myrokos has two more jobs; take both. Barton leads a Syndicate scouting party at Strahnbrad, in the east of the Alterac Mountains, inside one of the houses with stealthed Syndicate around him. Pick his pocket for the report and do not kill him: he does not drop it. If you are lower than him he sees through stealth; Master of Deception helps, or Distract him, Vanish and come in from behind. Pick Pocket can miss several times in a row.",
			["Opens {area:3486}, the hidden rogue house in the Alterac hills, and {npc:13085}'s jobs against the Syndicate."] = "Opens Ravenholdt Manor, the hidden rogue house in the Alterac hills, and Myrokos's jobs against the Syndicate.",
			["{npc:266216} is inside {area:275}, the Syndicate fortress south of the manor; he can stand in any of fifteen spots in the keep, so search. Quick and quiet, says {npc:13085}. Pick the pockets of the level 20-21 Syndicate Rogues, Shadow Mages and Watchmen on your way: they carry {quest:6701} for the guards' repeatable reputation quest."] = "Lord Tomas is inside Durnholde Keep, the Syndicate fortress south of the manor; he can stand in any of fifteen spots in the keep, so search. Quick and quiet, says Myrokos. Pick the pockets of the level 20-21 Syndicate Rogues, Shadow Mages and Watchmen on your way: they carry Syndicate Emblems for the guards' repeatable reputation quest.",
		},
		zone = 1424,
		zoneName = "Hillsbrad Foothills",
	}
end)

